import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatCard, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
import { ExtendForm, FreeToggle } from "@/components/SubscriptionControls";

export const dynamic = "force-dynamic";

export default async function AdminSubscriptions() {
  await requireArea("billing");

  const [servers, revenueAgg] = await Promise.all([
    db.server.findMany({
      where: { status: { notIn: ["DELETING"] } },
      include: { user: true, plan: true },
      orderBy: [{ isFree: "asc" }, { expiresAt: "asc" }],
    }),
    db.walletTransaction.aggregate({
      where: { amountCents: { lt: 0 } },
      _sum: { amountCents: true },
    }),
  ]);

  const paid = servers.filter((s) => !s.isFree);
  const mrrCents = paid.reduce((sum, s) => sum + s.plan.priceCents, 0);
  const totalRevenueCents = -(revenueAgg._sum.amountCents ?? 0);
  const now = Date.now();
  const overdue = paid.filter((s) => s.expiresAt && s.expiresAt.getTime() < now);

  return (
    <div className="space-y-6">
      <PageHeader title="Subscriptions" sub="Renewal state of every server on the platform." />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-5">
        <StatCard label="Active subscriptions" value={String(paid.length)} />
        <StatCard label="Free servers" value={String(servers.length - paid.length)} delta="no billing" />
        <StatCard label="MRR" value={fmtMoney(mrrCents)} href="/admin/analytics" />
        <StatCard label="Lifetime revenue" value={fmtMoney(totalRevenueCents)} href="/admin/billing" />
        <StatCard
          label="Overdue"
          value={String(overdue.length)}
          delta={overdue.length > 0 ? "past renewal date" : "all current"}
          deltaGood={overdue.length === 0}
        />
      </div>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Server</th>
              <th>Client</th>
              <th>Plan</th>
              <th>Status</th>
              <th>Auto-renew</th>
              <th>Paid until</th>
              <th>Adjust</th>
              <th className="text-right">Billing mode</th>
            </tr>
          </thead>
          <tbody>
            {servers.length === 0 && (
              <tr>
                <td colSpan={8} className="py-10 text-center text-slate-500">
                  No servers yet.
                </td>
              </tr>
            )}
            {servers.map((s) => {
              const isOverdue = !s.isFree && s.expiresAt && s.expiresAt.getTime() < now;
              return (
                <tr key={s.id} className={isOverdue ? "bg-red-500/[0.04]" : undefined}>
                  <td>
                    <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
                      {s.hostname}
                    </Link>
                    {s.isFree && (
                      <span className="ml-2">
                        <Badge tone="green">free</Badge>
                      </span>
                    )}
                  </td>
                  <td>
                    <Link href={`/admin/users/${s.userId}`} className="text-slate-300 hover:text-brand-300">
                      {s.user.email}
                    </Link>
                  </td>
                  <td>
                    {s.plan.name}
                    {!s.isFree && <span className="text-xs text-slate-500"> · {fmtMoney(s.plan.priceCents)}/mo</span>}
                  </td>
                  <td>
                    <StatusDot status={s.status} />
                  </td>
                  <td>
                    {s.isFree ? (
                      <span className="text-slate-500">—</span>
                    ) : (
                      <Badge tone={s.autoRenew ? "green" : "slate"}>{s.autoRenew ? "on" : "off"}</Badge>
                    )}
                  </td>
                  <td className={isOverdue ? "font-semibold text-red-400" : ""}>
                    {s.isFree ? "never expires" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
                    {isOverdue && (
                      <span className="ml-2">
                        <Badge tone="red">overdue</Badge>
                      </span>
