import Script from "next/script";

/**
 * Provider-agnostic live-chat scaffold. Renders nothing unless configured, so it
 * is safe to mount unconditionally in the root layout.
 *
 * Configuration precedence (first match wins):
 *   1. `snippet` prop — raw provider <script> body from the `livechat_snippet`
 *      Setting. Because this is a client component it cannot read the DB itself;
 *      a server parent (the layout) reads the Setting and passes it down.
 *   2. NEXT_PUBLIC_CRISP_ID  — Crisp website ID.
 *   3. NEXT_PUBLIC_TAWK_ID   — tawk.to property/widget id, formatted
 *      "<propertyId>/<widgetId>" (or just "<propertyId>" → default widget).
 *
 * No hard dependency on any provider; all three paths are optional.
 */
export default function LiveChat({ snippet }: { snippet?: string } = {}) {
  const raw = snippet?.trim();
  const crispId = process.env.NEXT_PUBLIC_CRISP_ID;
  const tawkId = process.env.NEXT_PUBLIC_TAWK_ID;

  // 1. Custom snippet from the livechat_snippet Setting (any provider).
  if (raw) {
    return (
      <Script id="livechat-custom" strategy="afterInteractive">
        {raw}
      </Script>
    );
  }

  // 2. Crisp.
  if (crispId) {
    return (
      <Script id="livechat-crisp" strategy="afterInteractive">
        {`window.$crisp=[];window.CRISP_WEBSITE_ID="${crispId}";(function(){var d=document,s=d.createElement("script");s.src="https://client.crisp.chat/l.js";s.async=1;d.getElementsByTagName("head")[0].appendChild(s);})();`}
      </Script>
    );
  }

  // 3. tawk.to.
  if (tawkId) {
    const [propertyId, widgetId = "default"] = tawkId.split("/");
    return (
      <Script id="livechat-tawk" strategy="afterInteractive">
        {`var Tawk_API=Tawk_API||{},Tawk_LoadStart=new Date();(function(){var s1=document.createElement("script"),s0=document.getElementsByTagName("script")[0];s1.async=true;s1.src="https://embed.tawk.to/${propertyId}/${widgetId}";s1.charset="UTF-8";s1.setAttribute("crossorigin","*");s0.parentNode.insertBefore(s1,s0);})();`}
      </Script>
    );
  }

  // Not configured → render nothing.
  return null;
}
