  expiresAt: Date | null;
};

/** Monthly-normalized price for a subscription billed every `termMonths`. */
export function monthlyCents(priceCents: number, termMonths: number): number {
  const t = Number.isFinite(termMonths) && termMonths > 0 ? termMonths : 1;
  return Math.round(priceCents / t);
}

function ExpiryCell({ expiresAt, now }: { expiresAt: Date | null; now: number }) {
  if (!expiresAt) return <span className="text-slate-500">—</span>;
  const overdue = expiresAt.getTime() < now;
  return (
    <span className={overdue ? "font-semibold text-red-400" : undefined}>
      {expiresAt.toISOString().slice(0, 10)}
      {overdue && (
        <span className="ml-2">
          <Badge tone="red">overdue</Badge>
        </span>
      )}
    </span>
  );
}

function ClientCell({ userId, email }: { userId: string; email: string }) {
  return (
    <Link href={`/admin/users/${userId}`} className="text-slate-300 hover:text-brand-300">
