    expiresAt: v.expiresAt,
  }));

  const emailMrrCents = emailRows
    .filter((r) => LIVE_EMAIL_STATUSES.has(r.status))
    .reduce((sum, r) => sum + monthlyCents(r.planPriceCents, r.planTermMonths), 0);
  const volumeMrrCents = volumeRows
    .filter((r) => LIVE_VOLUME_STATUSES.has(r.status))
    .reduce((sum, r) => sum + r.priceCents, 0);
  const totalMrrCents = emailMrrCents + volumeMrrCents;

  // Gross (tax-inclusive) recurring figure using the configured tax_percent.
  const gross = await applyTaxFromSettings(totalMrrCents);

  const mailboxTotal = emailRows.reduce((sum, r) => sum + r.mailboxCount, 0);
  const provisionedGB = volumeRows.reduce((sum, r) => sum + r.sizeGB, 0);
  const attached = volumeRows.filter((r) => r.status === "ATTACHED").length;

  const now = Date.now();
  const lapsing = [...emailRows, ...volumeRows].filter(
    (r) => r.expiresAt && r.expiresAt.getTime() < now + 7 * 86400_000,
  ).length;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Add-on products"
        sub="Business email and block storage sold on top of VPS plans — who has what, and what it earns."
      />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-5">
        <StatCard
          label="Email subscriptions"
          value={String(emailRows.length)}
          delta={`${mailboxTotal} mailbox${mailboxTotal === 1 ? "" : "es"}`}
        />
        <StatCard
          label="Volumes"
          value={String(volumeRows.length)}
          delta={`${attached} attached · ${provisionedGB} GB`}
        />
        <StatCard label="Email MRR" value={formatMoney(emailMrrCents, currency)} />
        <StatCard label="Storage MRR" value={formatMoney(volumeMrrCents, currency)} />
        <StatCard
          label="Expiring ≤ 7 days"
          value={String(lapsing)}
          delta={lapsing > 0 ? "needs renewal" : "all current"}
          deltaGood={lapsing === 0}
        />
      </div>

      <div className="card max-w-md p-5">
        <div className="mb-3 flex items-center justify-between gap-3">
          <h2 className="text-sm font-semibold text-slate-200">Combined add-on MRR</h2>
          <Badge tone="slate">{currency}</Badge>
        </div>
        <TaxLine
          netCents={totalMrrCents}
          taxPercent={rate}
          currency={currency}
          netLabel="Net recurring"
          totalLabel="Gross recurring"
        />
        <p className="mt-3 text-xs text-slate-500">
          {rate > 0
            ? `Includes ${rate}% tax/VAT — ${formatMoney(gross.tax, currency)} of ${formatMoney(gross.total, currency)}.`
            : "No tax rate configured. Set one under Settings → Billing."}
        </p>
      </div>

      <section className="space-y-3">
        <h2 className="text-lg font-semibold">Business email</h2>
        <EmailSubscriptionTable rows={emailRows} currency={currency} />
      </section>

      <section className="space-y-3">
        <h2 className="text-lg font-semibold">Block storage</h2>
        <VolumeTable rows={volumeRows} currency={currency} />
      </section>
    </div>
  );
}
